/** Original launcher services. No dependency on any other Android launcher. */
public final class Core {
 public interface Progress { void update(String message); }
 public static final AtomicBoolean cancel=new AtomicBoolean();
 public static final ExecutorService WORK=Executors.newSingleThreadExecutor();
 public static void check() throws IOException {if(cancel.get()||Thread.currentThread().isInterrupted())throw new InterruptedIOException("Cancelled");}
 public static String text(File f)throws IOException{return new String(Files.readAllBytes(f.toPath()),StandardCharsets.UTF_8);}
 public static JSONObject read(File f)throws Exception{return new JSONObject(text(f));}
 public static synchronized void write(File f,String s)throws IOException{f.getParentFile().mkdirs();File p=new File(f.getParentFile(),f.getName()+".tmp");try(FileOutputStream o=new FileOutputStream(p)){o.write(s.getBytes(StandardCharsets.UTF_8));o.getFD().sync();}Files.move(p.toPath(),f.toPath(),StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}
 public static File inside(File root,String name)throws IOException{File f=new File(root,name).getCanonicalFile();if(!f.getPath().startsWith(root.getCanonicalPath()+File.separator))throw new IOException("Unsafe file path");return f;}
 public static String hex(byte[] b){StringBuilder s=new StringBuilder();for(byte x:b)s.append(String.format(Locale.ROOT,"%02x",x&255));return s.toString();}
 public static HttpURLConnection connection(String url)throws Exception{URL u=new URL(url);if(!"https".equals(u.getProtocol()))throw new IOException("Only HTTPS downloads are allowed");HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setConnectTimeout(20000);c.setReadTimeout(30000);c.setRequestProperty("User-Agent","MinecraftJogger/0.3 (independent; github.com/itswiktoragain/gpt-on-the-move)");c.setInstanceFollowRedirects(false);return c;}
 public static HttpURLConnection get(String url)throws Exception{for(int i=0;i<6;i++){check();HttpURLConnection c=connection(url);int status=c.getResponseCode();if(status>=300&&status<400){String l=c.getHeaderField("Location");URL next=new URL(new URL(url),l);c.disconnect();url=next.toString();continue;}if(status!=200){c.disconnect();throw new IOException("Download HTTP "+status+" from "+new URL(url).getHost());}return c;}throw new IOException("Too many redirects");}
 public static String fetch(String url)throws Exception{HttpURLConnection c=get(url);try(InputStream in=c.getInputStream()){ByteArrayOutputStream b=new ByteArrayOutputStream();copy(in,b,32*1024*1024);return b.toString("UTF-8");}finally{c.disconnect();}}
 public static JSONObject request(String url,JSONObject body,String form,String bearer)throws Exception{HttpURLConnection c=connection(url);c.setRequestMethod(body!=null||form!=null?"POST":"GET");if(bearer!=null)c.setRequestProperty("Authorization","Bearer "+bearer);if(body!=null||form!=null){c.setDoOutput(true);c.setRequestProperty("Content-Type",form!=null?"application/x-www-form-urlencoded":"application/json");try(OutputStream o=c.getOutputStream()){o.write((form!=null?form:body.toString()).getBytes(StandardCharsets.UTF_8));}}int code=c.getResponseCode();try(InputStream i=code>=400?c.getErrorStream():c.getInputStream()){if(i==null)throw new IOException("Authentication HTTP "+code);ByteArrayOutputStream b=new ByteArrayOutputStream();copy(i,b,2*1024*1024);JSONObject j=new JSONObject(b.toString("UTF-8"));j.put("_http",code);return j;}finally{c.disconnect();}}
 public static void copy(InputStream i,OutputStream o,long max)throws IOException{byte[] b=new byte[65536];long n=0;int r;while((r=i.read(b))!=-1){check();n+=r;if(n>max)throw new IOException("File exceeds size limit");o.write(b,0,r);}}
 public static String hash(File f,String alg)throws Exception{MessageDigest d=MessageDigest.getInstance(alg);try(InputStream i=new FileInputStream(f)){byte[]b=new byte[65536];int n;while((n=i.read(b))!=-1){check();d.update(b,0,n);}}return hex(d.digest());}
 public static void download(String url,File f,String hash,String alg)throws Exception{check();if(f.isFile()&&f.length()>0&&hash!=null&&!hash.isEmpty()&&hash(f,alg).equalsIgnoreCase(hash))return;f.getParentFile().mkdirs();File p=new File(f.getParentFile(),f.getName()+".part");HttpURLConnection c=get(url);long expected=c.getContentLengthLong();try{try(InputStream i=c.getInputStream();FileOutputStream o=new FileOutputStream(p)){copy(i,o,1024L*1024*1024);o.getFD().sync();}if(expected>=0&&p.length()!=expected)throw new IOException("Truncated download: "+f.getName());if(hash!=null&&!hash.isEmpty()&&!hash(p,alg).equalsIgnoreCase(hash))throw new IOException("Checksum mismatch: "+f.getName());check();Files.move(p.toPath(),f.toPath(),StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}finally{c.disconnect();p.delete();}}
 public static final class Store {
  public final Context c;public final File root,instances,cache;public final android.content.SharedPreferences prefs;
  public Store(Context c){this.c=c;root=new File(c.getFilesDir(),"jogger");instances=new File(root,"instances");cache=new File(root,"shared");instances.mkdirs();cache.mkdirs();prefs=c.getSharedPreferences("jogger",0);}
  public File dir(String id)throws IOException{if(id==null||!id.matches("[a-zA-Z0-9_-]{1,64}"))throw new IOException("Invalid instance");return inside(instances,id);}
  public JSONObject instance(String id)throws Exception{return read(new File(dir(id),"instance.json"));}
  public void save(JSONObject j)throws Exception{write(new File(dir(j.getString("id")),"instance.json"),j.toString(2));}
  public List<JSONObject> all(){List<JSONObject>a=new ArrayList<>();File[] fs=instances.listFiles();if(fs!=null)for(File f:fs)try{a.add(read(new File(f,"instance.json")));}catch(Exception ignored){}a.sort(Comparator.comparing(x->x.optString("name")));return a;}
  public JSONObject create(String name,String version,String loader)throws Exception{String id=UUID.randomUUID().toString();File d=dir(id);d.mkdirs();new File(d,"mods").mkdirs();new File(d,"resourcepacks").mkdirs();JSONObject j=new JSONObject().put("id",id).put("name",name).put("version",version).put("loader",loader).put("ram",2048).put("resolution",70).put("preset","Balanced");save(j);preset(d,"Balanced");return j;}
  public void preset(File dir,String mode)throws Exception{
   File file=new File(dir,"options.txt");LinkedHashMap<String,String> m=options(file);File backup=new File(dir,"jogger-options-backup.json");JSONObject old=backup.exists()?read(backup):new JSONObject();
   boolean battery=mode.equals("Battery"),quality=mode.equals("Quality");Map<String,String> p=new LinkedHashMap<>();p.put("renderDistance",quality?"10":battery?"4":"6");p.put("simulationDistance",quality?"6":"4");p.put("maxFps",battery?"30":"60");p.put("graphicsMode",quality?"1":"0");p.put("fancyGraphics",quality?"true":"false");p.put("renderClouds","false");p.put("particles",quality?"0":"1");p.put("entityDistanceScaling",quality?"1.0":"0.6");p.put("biomeBlendRadius",quality?"2":"0");p.put("mipmapLevels",quality?"3":"1");p.put("enableVsync","true");p.put("autoJump","true");
   for(Map.Entry<String,String> e:p.entrySet()){if(!old.has(e.getKey()))old.put(e.getKey(),m.containsKey(e.getKey())?m.get(e.getKey()):JSONObject.NULL);m.put(e.getKey(),e.getValue());}write(backup,old.toString());saveOptions(file,m);
  }
  public void restore(File dir)throws Exception{File backup=new File(dir,"jogger-options-backup.json");if(!backup.exists())return;JSONObject b=read(backup);LinkedHashMap<String,String>m=options(new File(dir,"options.txt"));for(Iterator<String>it=b.keys();it.hasNext();){String k=it.next();if(b.isNull(k))m.remove(k);else m.put(k,b.getString(k));}saveOptions(new File(dir,"options.txt"),m);backup.delete();}
 }
 public static LinkedHashMap<String,String> options(File f)throws Exception{LinkedHashMap<String,String>m=new LinkedHashMap<>();if(f.isFile())for(String l:text(f).split("\n")){int c=l.indexOf(':');if(c>0)m.put(l.substring(0,c),l.substring(c+1));}return m;}
 public static void saveOptions(File f,Map<String,String>m)throws Exception{StringBuilder b=new StringBuilder();for(Map.Entry<String,String>e:m.entrySet())b.append(e.getKey()).append(':').append(e.getValue()).append('\n');write(f,b.toString());}
 public static boolean rules(JSONArray rules)throws Exception{if(rules==null)return true;boolean allow=false;for(int i=0;i<rules.length();i++){JSONObject r=rules.getJSONObject(i);if(r.has("features"))continue;JSONObject os=r.optJSONObject("os");if(os!=null){if(!os.optString("name","linux").equals("linux"))continue;if(os.has("arch")){String a=Build.SUPPORTED_ABIS[0].equals("arm64-v8a")?"aarch64":"amd64";if(!a.matches(os.getString("arch")))continue;}if(os.has("version")&&!System.getProperty("os.version","").matches(os.getString("version")))continue;}allow=r.getString("action").equals("allow");}return allow;}
 public static final class Installer {
  final Store s;final Progress log;final List<String> cp=new ArrayList<>();
  public Installer(Store s,Progress log){this.s=s;this.log=log;}
  public File prepare(JSONObject instance,JSONObject account,boolean demo)throws Exception{
   cancel.set(false);String version=instance.getString("version");File dir=s.dir(instance.getString("id"));log.update("Reading official Minecraft version manifest");JSONObject manifest=new JSONObject(fetch("https://piston-meta.mojang.com/mc/game/version_manifest_v2.json"));JSONArray vs=manifest.getJSONArray("versions");JSONObject selected=null;for(int i=0;i<vs.length();i++)if(vs.getJSONObject(i).getString("id").equals(version)){selected=vs.getJSONObject(i);break;}if(selected==null)throw new IOException("Unknown Minecraft version");
   File metadata=inside(s.cache,"versions/"+version+".json");download(selected.getString("url"),metadata,selected.optString("sha1"),"SHA-1");JSONObject meta=read(metadata);if(meta.optJSONObject("javaVersion")!=null&&meta.getJSONObject("javaVersion").optInt("majorVersion",21)>21)throw new IOException("This build bundles Java 21; choose Minecraft 1.21.4 or another Java 21 version");
   boolean modern=false;JSONArray libs=meta.getJSONArray("libraries");for(int i=0;i<libs.length();i++)if(libs.getJSONObject(i).optString("name").startsWith("org.lwjgl:lwjgl:"))modern=true;if(!modern)throw new IOException("This native engine targets LWJGL 3 versions. Start with Minecraft 1.21.4.");
   cp.clear();log.update("Installing verified Java libraries");for(int i=0;i<libs.length();i++){JSONObject l=libs.getJSONObject(i);if(!rules(l.optJSONArray("rules")))continue;String name=l.getString("name");if(name.startsWith("org.lwjgl:"))continue;JSONObject ds=l.optJSONObject("downloads");if(ds==null||!ds.has("artifact"))continue;JSONObject a=ds.getJSONObject("artifact");File f=inside(s.cache,"libraries/"+a.getString("path"));download(a.getString("url"),f,a.optString("sha1"),"SHA-1");cp.add(f.getAbsolutePath());}
   for(String module:new String[]{"lwjgl","lwjgl-glfw","lwjgl-opengl","lwjgl-openal","lwjgl-stb","lwjgl-tinyfd","lwjgl-jemalloc"}){File f=inside(s.cache,"libraries/jogger/"+module+"-3.3.3.jar");if(!f.isFile())download("https://repo.maven.apache.org/maven2/org/lwjgl/"+module+"/3.3.3/"+module+"-3.3.3.jar",f,null,"SHA-256");cp.add(f.getAbsolutePath());}
   JSONObject client=meta.getJSONObject("downloads").getJSONObject("client");File jar=inside(s.cache,"versions/"+version+".jar");log.update("Downloading Minecraft client");download(client.getString("url"),jar,client.getString("sha1"),"SHA-1");cp.add(jar.getAbsolutePath());
   File mappings=inside(s.cache,"versions/"+version+"-mappings.txt");if(meta.getJSONObject("downloads").has("client_mappings")){JSONObject a=meta.getJSONObject("downloads").getJSONObject("client_mappings");download(a.getString("url"),mappings,a.getString("sha1"),"SHA-1");}
   JSONObject ai=meta.getJSONObject("assetIndex");File index=inside(s.cache,"assets/indexes/"+ai.getString("id")+".json");download(ai.getString("url"),index,ai.getString("sha1"),"SHA-1");JSONObject objects=read(index).getJSONObject("objects");List<String> names=new ArrayList<>();objects.keys().forEachRemaining(names::add);ExecutorService pool=Executors.newFixedThreadPool(4);AtomicInteger done=new AtomicInteger();List<Future<?>> futures=new ArrayList<>();try{for(String name:names){JSONObject a=objects.getJSONObject(name);String h=a.getString("hash");futures.add(pool.submit(()->{try{download("https://resources.download.minecraft.net/"+h.substring(0,2)+"/"+h,inside(s.cache,"assets/objects/"+h.substring(0,2)+"/"+h),h,"SHA-1");int n=done.incrementAndGet();if(n%50==0)log.update("Assets "+n+" / "+names.size());}catch(Exception e){throw new CompletionException(e);}}));}for(Future<?>f:futures)f.get();}finally{pool.shutdownNow();}
   String main=meta.getString("mainClass");String loader=instance.optString("loader","Vanilla");
   if(!loader.equals("Vanilla")){if(demo)throw new IOException("Use a licensed account for mod-loader instances; the Demo button is vanilla only");String host=loader.equals("Fabric")?"https://meta.fabricmc.net/v2":"https://meta.quiltmc.org/v3";JSONArray loaders=new JSONArray(fetch(host+"/versions/loader/"+version));if(loaders.length()==0)throw new IOException("No loader available for this version");String lv=instance.optString("loaderVersion",loaders.getJSONObject(0).getJSONObject("loader").getString("version"));JSONObject profile=new JSONObject(fetch(host+"/versions/loader/"+version+"/"+lv+"/profile/json"));main=profile.getString("mainClass");JSONArray ml=profile.getJSONArray("libraries");for(int i=0;i<ml.length();i++){JSONObject l=ml.getJSONObject(i);String[]m=l.getString("name").split(":");String path=m[0].replace('.','/')+"/"+m[1]+"/"+m[2]+"/"+m[1]+"-"+m[2]+".jar";File f=inside(s.cache,"libraries/"+path);if(!f.isFile())download(l.optString("url","https://libraries.minecraft.net/")+path,f,null,"SHA-256");cp.add(0,f.getAbsolutePath());}write(new File(dir,"loader-profile.json"),profile.toString(2));}
   File runtime=runtime(s.c,log);File agent=new File(s.root,"jogger-agent.jar");try(InputStream in=s.c.getAssets().open("jogger-agent.jar");FileOutputStream out=new FileOutputStream(agent)){copy(in,out,8*1024*1024);}
   extractTextures(jar,dir);String nd=s.c.getApplicationInfo().nativeLibraryDir;JSONObject engine=new JSONObject(assetText(s.c,"engine.json"));String renderer=nd+"/"+engine.getString("renderer");
   List<String> opts=new ArrayList<>(Arrays.asList("-Xms256m","-Xmx"+Math.max(768,Math.min(6144,instance.optInt("ram",2048)))+"m","-XX:+UseG1GC","-XX:ActiveProcessorCount=4","-Djava.home="+runtime,"-Djava.io.tmpdir="+dir,"-Duser.home="+dir,"-Djava.awt.headless=true","-Dorg.lwjgl.system.allocator=system","-Dorg.lwjgl.librarypath="+nd,"-Djava.library.path="+nd+":"+runtime+"/lib","-Dorg.lwjgl.glfw.libname="+nd+"/libglfw_jogger.so","-Dorg.lwjgl.opengl.libname="+renderer,"-Dorg.lwjgl.openal.libname="+nd+"/libopenal.so","-Dorg.lwjgl.system.SharedLibraryExtractPath="+new File(s.root,"native-cache"),"-Djogger.dir="+dir,"-Djogger.mappings="+mappings,"-Djogger.native="+nd+"/libglfw_jogger.so","-javaagent:"+agent,"-Djava.class.path="+String.join(File.pathSeparator,cp)));
   String uuid=demo?"00000000000000000000000000000000":account.getString("id"),user=demo?"Player":account.getString("name"),token=demo?"0":account.getString("mcToken");
   List<String> args=new ArrayList<>(Arrays.asList("--username",user,"--version",version,"--gameDir",dir.getAbsolutePath(),"--assetsDir",new File(s.cache,"assets").getAbsolutePath(),"--assetIndex",ai.getString("id"),"--uuid",uuid,"--accessToken",token,"--userType","msa","--versionType","release","--width","1280","--height","720"));if(demo)args.add("--demo");
   JSONObject launch=new JSONObject().put("runtime",runtime.toString()).put("renderer",renderer).put("main",main).put("jvm",new JSONArray(opts)).put("args",new JSONArray(args)).put("instance",instance.getString("id"));File plan=new File(s.c.getNoBackupFilesDir(),"launch.json");write(plan,launch.toString());log.update("Ready to start Minecraft");return plan;
  }
 }
 public static String assetText(Context c,String name)throws Exception{try(InputStream in=c.getAssets().open(name)){ByteArrayOutputStream out=new ByteArrayOutputStream();copy(in,out,2*1024*1024);return out.toString("UTF-8");}}
 public static File runtime(Context c,Progress p)throws Exception{File root=new File(c.getFilesDir(),"jogger/runtime21");if(new File(root,"release").isFile()&&new File(root,"lib/server/libjvm.so").isFile())return root;p.update("Installing bundled OpenJDK 21");String abi=Build.SUPPORTED_ABIS[0];if(!abi.equals("arm64-v8a")&&!abi.equals("x86_64"))throw new IOException("64-bit Android required");File stage=new File(root.getParentFile(),"runtime-stage");stage.mkdirs();long total=0;try(ZipInputStream z=new ZipInputStream(c.getAssets().open("runtime-"+abi+".zip"))){ZipEntry e;while((e=z.getNextEntry())!=null){File f=inside(stage,e.getName());if(e.isDirectory()){f.mkdirs();continue;}f.getParentFile().mkdirs();try(FileOutputStream out=new FileOutputStream(f)){copy(z,out,256L*1024*1024);}total+=f.length();if(total>600L*1024*1024)throw new IOException("Runtime archive too large");}}if(!new File(stage,"lib/server/libjvm.so").isFile())throw new IOException("Runtime archive is incomplete");if(root.exists())throw new IOException("Incomplete runtime exists; remove app runtime data and retry");if(!stage.renameTo(root))throw new IOException("Could not publish Java runtime");return root;}
 private static void extractTextures(File jar,File dir)throws Exception{try(ZipFile z=new ZipFile(jar)){String[]names={"assets/minecraft/textures/gui/sprites/widget/button.png","assets/minecraft/textures/gui/sprites/widget/button_highlighted.png","assets/minecraft/textures/gui/widgets.png"};for(String name:names){ZipEntry e=z.getEntry(name);if(e!=null){File dest=new File(dir,"jogger-ui/"+new File(name).getName());dest.getParentFile().mkdirs();try(InputStream in=z.getInputStream(e);FileOutputStream out=new FileOutputStream(dest)){copy(in,out,2*1024*1024);}}}}}
 public static void archive(File f,boolean pack)throws Exception{try(ZipFile z=new ZipFile(f)){if(pack&&z.getEntry("pack.mcmeta")==null)throw new IOException("Resource pack needs pack.mcmeta at ZIP root");if(!pack&&z.size()==0)throw new IOException("Empty JAR");}}
 private Core(){}
}
